import {makeAccount,submit,cancel,step,replay,equity,value,outcome} from './core/engine.mjs';
import {validateTapePackage} from './core/tape.mjs';
import {revisionChanges,compareAccounts,decisionStatus} from './core/review.mjs';
import {buildReport,explanation} from './core/report.mjs';
const $=id=>document.getElementById(id),date=t=>new Date(t).toISOString().slice(0,10),LC=window.LightweightCharts;
let catalog=[],chapter,source,account,revision=null,preview,selected,paused=true,budget=0,last=performance.now(),loadId=0,controller,signature='',clickAt=0,drawn=-1;
const style={autoSize:true,layout:{background:{color:'#15202b'},textColor:'#91a0ae',attributionLogo:true},grid:{vertLines:{color:'#22303d'},horzLines:{color:'#22303d'}},rightPriceScale:{borderColor:'#34414d'},timeScale:{timeVisible:false,borderColor:'#34414d'}};
const pc=LC.createChart($('priceChart'),style),ec=LC.createChart($('equityChart'),style),rc=LC.createChart($('reviewChart'),style);
const ps=pc.addSeries(LC.LineSeries,{color:'#72b1e6',lineWidth:2}),es=ec.addSeries(LC.AreaSeries,{lineColor:'#72b1e6',topColor:'#72b1e630',bottomColor:'#72b1e600'}),os=rc.addSeries(LC.LineSeries,{color:'#72b1e6',lineWidth:2}),rs=rc.addSeries(LC.LineSeries,{color:'#dcb976',lineStyle:LC.LineStyle.Dashed,lineWidth:2});
const amount=n=>(n/account.rules.cashScale).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),money=n=>amount(n)+' '+account.rules.quoteAsset;
const qty=n=>(n/account.rules.quantityScale).toLocaleString('en-US',{maximumFractionDigits:Math.ceil(Math.log10(account.rules.quantityScale))})+' '+account.rules.baseAsset;
const curve=a=>a.curve.map(([t,n])=>({time:date(t),value:n/a.rules.cashScale}));
function record(action,extra={}){account.practice.events.push({time:account.time,observedIndex:account.index,action,...extra});}
function setPaused(next,reason='Paused by you'){if(!account||account.done)return;paused=next;budget=0;last=performance.now();record(next?'pause':'resume');$('notice').textContent=next?reason:'Orders settle at the next unseen dated reference.';render();}
function advance(){if(!account||account.done)return;step(account,source.rows);budget=0;render();if(account.done){paused=true;$('notice').textContent=explanation(account);} }
function draw(){if(!account||drawn===account.index)return;ps.applyOptions({priceFormat:{type:'price',precision:Math.ceil(Math.log10(account.rules.priceScale)),minMove:1/account.rules.priceScale}});ps.setData(source.rows.slice(0,account.index+1).map(r=>({time:r[4],value:r[1]/account.rules.priceScale})));es.setData(curve(account));drawn=account.index;}
function render(){if(!account)return;const r=account.rules;
 $('equity').textContent=money(equity(account));$('cash').textContent=money(account.cash);$('positionValue').textContent=money(value(account.price,account.units,r));$('fees').textContent=money(account.fees);
 $('missionState').textContent=account.done?(outcome(account).passed?'Mandate met':'Mandate missed'):qty(Math.max(0,account.units-r.targetUnits))+' to reduce';
 $('clock').textContent=date(account.time);$('remaining').textContent=source.rows.length-1-account.index;$('age').textContent=account.done?'Settled':paused?'Paused':Math.max(0,Number($('cadence').value)-budget).toFixed(1)+' game seconds to next date';
 $('pause').textContent=account.done?'Settled':paused?'Resume':'Pause';$('pause').disabled=account.done;$('next').disabled=account.done;$('reviewBtn').disabled=!account.done;
 $('buy').disabled=paused||account.done;$('sell').disabled=paused||account.done;$('symbol').textContent=chapter.instrument.symbol;$('venue').textContent=chapter.instrument.venue+' · daily reference';
 $('price').textContent=(account.price/r.priceScale).toFixed(Math.ceil(Math.log10(r.priceScale)));$('priceUnit').textContent=r.quoteAsset+' per '+r.baseAsset;$('holding').textContent=qty(account.units);
 $('quantityCaption').textContent='Quantity · '+r.baseAsset;$('quantity').min=r.lotSizeUnits/r.quantityScale;$('quantity').step=r.lotSizeUnits/r.quantityScale;
 $('mandate').textContent=chapter.brief;$('execution').textContent='Next unseen dated reference. Fictional shared cap '+qty(r.referenceFillUnits)+' per observation. '+(r.sellLagObservations?'Newly bought units can be resold only at a later observation.':'No historical liquidity is inferred.');
 const n=Number($('quantity').value),u=Math.round(n*r.quantityScale);$('notional').textContent=Number.isSafeInteger(u)&&u>=0&&u<=r.maxOrderUnits&&Math.abs(u/r.quantityScale-n)<1e-9&&u%r.lotSizeUnits===0?money(value(account.price,u,r)):'—';
 $('position').textContent='Held '+qty(account.units)+' · marked at the last revealed reference.';$('equityUnit').textContent=r.quoteAsset+' · fictional funded account';
 $('orders').replaceChildren(...account.orders.slice().reverse().map(o=>{const d=document.createElement('div');d.className='order';const h=document.createElement('strong');h.textContent='#'+o.id+' '+o.side.toUpperCase()+' '+qty(o.units);const s=document.createElement('span');s.textContent=date(o.time)+' · '+qty(o.filledUnits||0)+' filled · '+decisionStatus(o,account);d.append(h,s);if(['pending','partial'].includes(o.status)&&!account.done){const b=document.createElement('button');b.textContent='Cancel remainder #'+o.id;b.disabled=paused;b.onclick=()=>{try{cancel(account,o.id);$('orderFeedback').textContent='Order #'+o.id+' remainder cancelled; completed fills retained.';render();}catch(e){$('orderFeedback').textContent=e.message;}};d.append(b);}return d;}));
 const recent=account.orders.at(-1);if(recent)$('orderFeedback').textContent='#'+recent.id+' '+qty(recent.filledUnits||0)+' of '+qty(recent.units)+' filled · '+decisionStatus(recent,account);draw();
}
async function read(url){controller?.abort();const ctrl=new AbortController();controller=ctrl;const timer=setTimeout(()=>ctrl.abort(),20000);try{const res=await fetch(url,{signal:ctrl.signal});if(!res.ok)throw Error('Historical package unavailable');return await res.json();}catch(e){if(e.name==='AbortError')throw Error('Loading timed out or was cancelled. Retry to continue.');throw e;}finally{clearTimeout(timer);if(controller===ctrl)controller=null;}}
async function select(c){if(!c){$('notice').textContent='Challenge catalog is not ready. Reload to retry.';return;}const request=++loadId;selected=c;preview=null;$('start').disabled=true;$('start').textContent='Checking daily observations…';$('briefDetails').textContent=c.brief;for(const b of $('choices').children)b.setAttribute('aria-pressed',String(b.dataset.id===c.id));
 try{const data=await read('data/'+c.file);await validateTapePackage(c,data);if(request!==loadId)return;preview={chapter:c,source:data};const p=document.createElement('p');p.textContent=c.brief;const s=document.createElement('strong');s.textContent=c.market+' · '+c.instrument.symbol+' · '+c.date+'–'+c.endDate+' · '+c.rows+' actual observation dates';$('briefDetails').replaceChildren(s,p);$('start').disabled=false;$('start').textContent=account&&!account.done&&chapter.id===c.id?'Resume current account':'Take over the account';}
 catch(e){if(request!==loadId)return;$('briefDetails').textContent=e.message+' No synthetic fallback is used.';$('start').disabled=false;$('start').textContent='Retry loading';}
}
function closePicker(){loadId++;controller?.abort();$('brief').close();}
$('choose').disabled=true;$('choose').onclick=()=>{if(!catalog.length){$('notice').textContent='Challenge catalog is not ready. Reload to retry.';return;}if(account&&!account.done)setPaused(true,'Paused while choosing a challenge.');$('backToAccount').hidden=!account;$('brief').showModal();select(chapter||catalog[0]);};
$('backToAccount').onclick=closePicker;$('brief').addEventListener('cancel',()=>{loadId++;controller?.abort();});
$('start').onclick=()=>{if(!preview){select(selected);return;}if(account&&!account.done&&chapter.id===preview.chapter.id){closePicker();setPaused(false);return;}({chapter,source}=preview);account=makeAccount(source.rows,chapter.rules);account.practice={mode:'fictional-date-reveals',events:[]};revision=null;drawn=-1;$('quantity').value=chapter.rules.referenceFillUnits/chapter.rules.quantityScale;$('orderError').hidden=true;$('orderFeedback').textContent='No orders yet.';closePicker();setPaused(false);record('reveal-cadence',{secondsPerObservation:Number($('cadence').value)});pc.timeScale().fitContent();};
function order(side){try{if(!account||paused||account.done)throw Error('Resume the challenge before placing an order');const now=performance.now(),sig=side+'|'+$('quantity').value;if(sig===signature&&now-clickAt<500)return;signature=sig;clickAt=now;const n=Number($('quantity').value),u=Math.round(n*account.rules.quantityScale);if(!$('quantity').value.trim()||!Number.isFinite(n)||Math.abs(u/account.rules.quantityScale-n)>1e-9)throw Error('Enter a valid quantity in the displayed order lots');const o=submit(account,{side,type:'market',units:u});$('orderError').hidden=true;$('orderFeedback').textContent='Order #'+o.id+' queued for the next unseen date.';render();}catch(e){$('orderError').textContent=e.message;$('orderError').hidden=false;}}
$('buy').onclick=()=>order('buy');$('sell').onclick=()=>order('sell');$('quantity').oninput=render;
$('half').onclick=()=>{if(!account)return;$('quantity').value=Math.max(account.rules.lotSizeUnits,Math.floor(account.units/2/account.rules.lotSizeUnits)*account.rules.lotSizeUnits)/account.rules.quantityScale;render();};
$('all').onclick=()=>{if(!account)return;$('quantity').value=Math.max(account.rules.lotSizeUnits,account.units)/account.rules.quantityScale;render();};
$('pause').onclick=()=>setPaused(!paused);$('next').onclick=()=>{advance();record('single-step');};$('cadence').onchange=()=>{budget=0;if(account&&!account.done)record('reveal-cadence',{secondsPerObservation:Number($('cadence').value)});render();};$('latest').onclick=()=>pc.timeScale().fitContent();
$('sourceBtn').onclick=()=>{if(!account)return;$('rulesText').textContent=chapter.brief;$('transformation').textContent=source.transformation;$('limits').replaceChildren(...source.limitations.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('provenance').textContent=source.timestampSemantics+'. Source SHA-256: '+source.sourceSha256+'. Normalized rows SHA-256: '+source.normalizedRowsSha256;$('attribution').textContent=source.rights.attribution;$('terms').href=source.rights.terms;$('rules').showModal();if(!account.done)setPaused(true,'Paused while viewing data and rules.');};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
function drawReview(){os.setData(curve(account));rs.setData(revision?curve(revision):[]);rc.timeScale().fitContent();}
function invalidate(){revision=null;$('comparison').replaceChildren();$('comparisonStatus').textContent='Inputs changed. Compare again to recalculate.';$('download').textContent='Download original report';$('record').textContent=JSON.stringify({chapter:chapter.id,original:account},null,2);drawReview();}
$('reviewBtn').onclick=()=>{if(!account?.done)return;$('originalResult').textContent='Original: '+(outcome(account).passed?'mandate met':'mandate missed')+' · '+money(equity(account))+'. '+explanation(account);$('edits').replaceChildren(...account.orders.filter(o=>!o.automatic).map(o=>{const d=document.createElement('div');d.className='edit';const l=document.createElement('label');l.textContent='#'+o.id+' · '+date(o.time)+' '+o.side+' · original '+qty(o.units);const input=document.createElement('input');input.type='number';input.step=account.rules.lotSizeUnits/account.rules.quantityScale;input.min='0';input.value=o.units/account.rules.quantityScale;input.dataset.id=o.id;input.setAttribute('aria-label','Revised quantity for order '+o.id);input.oninput=invalidate;d.append(l,input);for(const [name,u]of [['Skip',0],['Restore',o.units]]){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{input.value=u/account.rules.quantityScale;invalidate();};d.append(b);}return d;}));$('compare').disabled=!account.orders.some(o=>!o.automatic);$('review').showModal();invalidate();$('comparisonStatus').textContent='Change up to two decisions or compare unchanged.';};
$('compare').onclick=()=>{try{const changes=revisionChanges(account,Object.fromEntries([...$('edits').querySelectorAll('input')].map(i=>[i.dataset.id,i.value])));revision=replay(source.rows,account.orders,changes,account.rules);const c=compareAccounts(account,revision);$('comparisonStatus').textContent=c.changed.length+' of 2 decisions changed. Original '+(c.original.passed?'met':'missed')+' → revised '+(c.revised.passed?'met':'missed')+' the mandate. Original result unchanged.';const table=document.createElement('table');const caption=document.createElement('caption');caption.textContent='Monetary amounts in '+account.rules.quoteAsset+'; quantities in '+account.rules.baseAsset+'.';table.append(caption);for(const row of [['At close','Original','Revised'],['Equity',amount(c.original.equity),amount(c.revised.equity)],['Cash',amount(account.cash),amount(revision.cash)],['Marked position',amount(c.original.equity-account.cash),amount(c.revised.equity-revision.cash)],['Fees',amount(account.fees),amount(revision.fees)],['Units held',String(account.units/account.rules.quantityScale),String(revision.units/account.rules.quantityScale)]]){const tr=document.createElement('tr');row.forEach((s,i)=>{const td=document.createElement(i?'td':'th');td.textContent=s;tr.append(td);});table.append(tr);}const box=$('comparison');box.replaceChildren(table);const add=s=>{const p=document.createElement('p');p.textContent=s;box.append(p);};add(explanation(revision));add('Equity change '+money(c.equityDelta)+' = cash change '+money(c.cashDelta)+' + marked-position change '+money(c.positionDelta)+'. Fees are included in cash.');for(const {original:o,revised:n}of c.affected)add('Order #'+o.id+(o.units!==n.units?' edited':' affected by earlier decisions')+': requested '+qty(o.units)+' → '+qty(n.units)+'; filled '+qty(o.filledUnits||0)+' → '+qty(n.filledUnits||0)+'. '+decisionStatus(o,account)+' → '+decisionStatus(n,revision)+'. Last fill: '+(o.fillTime===undefined?'none':date(o.fillTime))+' → '+(n.fillTime===undefined?'none':date(n.fillTime))+'.');add('Submission and cancellation dates remain fixed. Repeated play is known-history practice; reference-price fills are fictional.');$('download').textContent='Download comparison report';$('record').textContent=JSON.stringify({chapter:chapter.id,changes,original:account,revised:revision},null,2);drawReview();}catch(e){invalidate();$('comparisonStatus').textContent=e.message;}};
$('download').onclick=()=>{const b=new Blob([buildReport(chapter,source,account,revision)],{type:'text/plain'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=chapter.id+'-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('visibilitychange',()=>{last=performance.now();budget=0;if(document.hidden&&account&&!account.done)setPaused(true,'Paused when this tab was hidden. Resume to continue.');});
function frame(now){const elapsed=(now-last)/1000;last=now;if(account&&!account.done&&!paused&&!document.hidden){budget+=elapsed;while(budget>=Number($('cadence').value)&&!account.done)advance();$('age').textContent=account.done?'Settled':Math.max(0,Number($('cadence').value)-budget).toFixed(1)+' game seconds to next date';}requestAnimationFrame(frame);}requestAnimationFrame(frame);
try{const data=await read('data/reference-chapters.json');if(!Array.isArray(data)||!data.length)throw Error('Challenge catalog is unavailable');catalog=data;$('choices').replaceChildren(...catalog.map(c=>{const b=document.createElement('button');b.className='choice';b.dataset.id=c.id;b.textContent=c.title;const small=document.createElement('small');small.textContent=c.market+' · '+c.instrument.symbol+' · '+c.date+'–'+c.endDate;b.append(small);b.onclick=()=>select(c);return b;}));$('choose').disabled=false;$('brief').showModal();await select(catalog[0]);}catch(e){$('choose').disabled=true;$('notice').textContent=e.message+' Reload to retry.';}
